import org.junit.*;
import org.junit.Before;
import org.junit.Test;
import org.mockito.Mockito;
import static org.junit.Assert.*;
import static org.junit.Assert.assertEquals;
import static org.mockito.Mockito.mock;
import static org.mockito.Mockito.when;

public class CoreFunction_functionCeiling_TriageGen0Test {

    private EvalContext mockContext;
    private Expression mockArg1;

    @Before
    public void setUp() {
        mockContext = mock(EvalContext.class);
        mockArg1 = mock(Expression.class);
    }

    /**
     * Helper class to expose the protected method for testing.
     */
    private static class TestableCoreFunction extends CoreFunction {
        public TestableCoreFunction(int functionCode, Expression[] args) {
            super(functionCode, args);
        }

        @Override
        public Object compute(EvalContext context) {
            // Since functionCeiling is protected and called via compute in the real flow,
            // we invoke it directly here to test the logic.
            return functionCeiling(context);
        }
    }

    @Test
    public void testFunctionCeiling_PositiveDecimal() throws Exception {
        Expression[] args = new Expression[]{mockArg1};
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(3.14);

        Object result = function.compute(mockContext);

        assertEquals(Double.valueOf(4.0), result);
    }

    @Test
    public void testFunctionCeiling_PositiveInteger() throws Exception {
        Expression[] args = new Expression[]{mockArg1};
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(5.0);

        Object result = function.compute(mockContext);

        assertEquals(Double.valueOf(5.0), result);
    }

    @Test
    public void testFunctionCeiling_NegativeDecimal() throws Exception {
        Expression[] args = new Expression[]{mockArg1};
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        // Math.ceil(-3.14) is -3.0
        when(mockArg1.computeValue(mockContext)).thenReturn(-3.14);

        Object result = function.compute(mockContext);

        assertEquals(Double.valueOf(-3.0), result);
    }

    @Test
    public void testFunctionCeiling_Zero() throws Exception {
        Expression[] args = new Expression[]{mockArg1};
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(0.0);

        Object result = function.compute(mockContext);

        assertEquals(Double.valueOf(0.0), result);
    }

    @Test
    public void testFunctionCeiling_NegativeInteger() throws Exception {
        Expression[] args = new Expression[]{mockArg1};
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(-5.0);

        Object result = function.compute(mockContext);

        assertEquals(Double.valueOf(-5.0), result);
    }

    @Test(expected = RuntimeException.class)
    public void testFunctionCeiling_WrongArgumentCount() throws Exception {
        // The method calls assertArgCount(1). 
        // If we provide 0 or 2 arguments, it should throw an exception.
        // Note: Depending on CoreFunction implementation, assertArgCount might throw AssertionError or RuntimeException.
        Expression[] args = new Expression[]{}; 
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        function.compute(mockContext);
    }

    @Test
    public void testFunctionCeiling_LargeValue() throws Exception {
        Expression[] args = new Expression[]{mockArg1};
        TestableCoreFunction function = new TestableCoreFunction(1, args);

        when(mockArg1.computeValue(mockContext)).thenReturn(Double.MAX_VALUE);

        Object result = function.compute(mockContext);

        assertEquals(Double.valueOf(Double.MAX_VALUE), result);
    }
}
